import assert from 'node:assert/strict';
import fs from 'node:fs';
import {runRetainedTileProof} from './consumer.mjs';
const name=process.env.NAUTILUS_TILE_PROOF_PACKAGE,T=await import(name+'/tiles'),proof=runRetainedTileProof(T),base=new URL('./node_modules/'+name+'/',import.meta.url),request=JSON.parse(fs.readFileSync(new URL('docs/reviews/procedural-tiles/registration-request.json',base))),declared=process.env.NAUTILUS_TILE_PROOF_DECLARED==='true';
for(const file of request.supportFiles)assert.ok(fs.existsSync(new URL(file,base)),file);if(!declared)assert.equal(fs.existsSync(new URL('vendor/',base)),false,'Private candidate has no donor renderer/runtime.');assert.equal(T.TILE_STATUSES.gameplay.support,'unbound');assert.match(T.tileUsageCard().status,/review/);
let installedRegistration=null;if(declared){const contracts=await import(name+'/contracts'),pkg=JSON.parse(fs.readFileSync(new URL('package.json',base)));assert.equal(pkg.exports['./tiles'],'./packages/tiles-core/index.js');const schemas=request.schemas.map(expected=>{const actual=contracts.schemaDocuments().find(s=>s.id===expected.id&&s.version===1);assert.equal(actual.uri,expected.uri);assert.equal(actual.url,new URL(expected.file,base).href);assert.equal(JSON.parse(fs.readFileSync(new URL(actual.url))).$id,expected.uri);assert.ok(pkg.files.includes(expected.file));return {id:actual.id,uri:actual.uri,url:actual.url};});assert.deepEqual(contracts.ENGINE_MANIFEST.capabilities.find(c=>c.id===request.engineCapability.id).versions,[1]);for(const id of request.hostPromisesMustNotBeInEngineManifest)assert.equal(contracts.ENGINE_MANIFEST.capabilities.some(c=>c.id===id),false);installedRegistration={entry:pkg.exports['./tiles'],schemas};}
console.log(JSON.stringify({status:'pass',declared,availability:declared?'Actual declared core package; adoption remains separate':'EXPLICIT PRIVATE OVERLAY; partial availability, root registration pending',proof,installedRegistration,supportFiles:request.supportFiles,cleanup:'Consumer owns no server/browser/watcher or retained helper.'}));
